// ---- Node-name -> account label map (this is how each result is tagged) ----
const ACCOUNT_BY_NODE = {
  'Stripe BCEO Main: Charges': 'bceo_main',
  'Stripe BCEO Main: Invoices': 'bceo_main',
  'Stripe BCEO Main: Subscriptions': 'bceo_main',
  'Stripe Convert&Flow: Charges': 'convert_and_flow',
  'Stripe Convert&Flow: Invoices': 'convert_and_flow',
  'Stripe Convert&Flow: Subscriptions': 'convert_and_flow',
};

function normEmail(v) {
  return (v || '').toString().trim().toLowerCase();
}
function normKey(v) {
  return (v || '').toString().trim().toLowerCase();
}

// Flatten every paginated page of a Stripe list node into one flat array of
// objects, tagging each with the account label the node belongs to.
function flatten(nodeName) {
  const account = ACCOUNT_BY_NODE[nodeName];
  const pages = $(nodeName).all();
  const out = [];
  for (const page of pages) {
    const body = page.json || {};
    const data = Array.isArray(body.data) ? body.data : [];
    for (const obj of data) {
      out.push({ obj, account });
    }
  }
  return out;
}

const charges = [
  ...flatten('Stripe BCEO Main: Charges'),
  ...flatten('Stripe Convert&Flow: Charges'),
];
const invoices = [
  ...flatten('Stripe BCEO Main: Invoices'),
  ...flatten('Stripe Convert&Flow: Invoices'),
];
const subscriptions = [
  ...flatten('Stripe BCEO Main: Subscriptions'),
  ...flatten('Stripe Convert&Flow: Subscriptions'),
];

const fleetRows = $('Load Fleet Standing').all().map(i => i.json || {});

// records: key -> record
const records = new Map();

function getRecord(account, key, seedId, seedEmail, seedName) {
  const fullKey = account + '::' + key;
  if (!records.has(fullKey)) {
    records.set(fullKey, {
      account: account,
      key: fullKey,
      customer_id: seedId || null,
      emails: new Set(),
      names: new Set(),
      failed_charge_count: 0,
      last_failed_charge_at: null,
      open_invoice_count: 0,
      max_attempt_count: 0,
      oldest_open_invoice_at: null,
      bad_subscription_statuses: new Set(),
    });
  }
  const rec = records.get(fullKey);
  if (!rec.customer_id && seedId) rec.customer_id = seedId;
  if (seedEmail) rec.emails.add(normEmail(seedEmail));
  if (seedName) rec.names.add(seedName.toString().trim());
  return rec;
}

function keyFor(customerId, email) {
  if (customerId) return { key: 'cust::' + customerId, id: customerId };
  if (email) return { key: 'email::' + normEmail(email), id: null };
  return null;
}

// ---- Failed charges (status === 'failed') ----
for (const { obj: charge, account } of charges) {
  if (charge.status !== 'failed') continue;
  const customerId = typeof charge.customer === 'string' ? charge.customer : (charge.customer && charge.customer.id) || null;
  const email = (charge.billing_details && charge.billing_details.email) || charge.receipt_email || null;
  const name = (charge.billing_details && charge.billing_details.name) || null;
  const k = keyFor(customerId, email);
  if (!k) continue; // no id and no email -> cannot key or attribute, skip
  const rec = getRecord(account, k.key, customerId, email, name);
  rec.failed_charge_count += 1;
  if (charge.created && (!rec.last_failed_charge_at || charge.created > rec.last_failed_charge_at)) {
    rec.last_failed_charge_at = charge.created;
  }
}

// ---- Open / uncollectible invoices ----
for (const { obj: invoice, account } of invoices) {
  if (invoice.status !== 'open' && invoice.status !== 'uncollectible') continue;
  const customerId = typeof invoice.customer === 'string' ? invoice.customer : (invoice.customer && invoice.customer.id) || null;
  const email = invoice.customer_email || (invoice.customer && invoice.customer.email) || null;
  const name = invoice.customer_name || (invoice.customer && invoice.customer.name) || null;
  const k = keyFor(customerId, email);
  if (!k) continue;
  const rec = getRecord(account, k.key, customerId, email, name);
  rec.open_invoice_count += 1;
  const attemptCount = invoice.attempt_count || 0;
  if (attemptCount > rec.max_attempt_count) rec.max_attempt_count = attemptCount;
  if (invoice.created && (!rec.oldest_open_invoice_at || invoice.created < rec.oldest_open_invoice_at)) {
    rec.oldest_open_invoice_at = invoice.created;
  }
}

// ---- Bad subscription statuses (past_due / unpaid) ----
for (const { obj: sub, account } of subscriptions) {
  if (sub.status !== 'past_due' && sub.status !== 'unpaid') continue;
  const customerObj = sub.customer;
  const customerId = typeof customerObj === 'object' ? customerObj.id : customerObj;
  const email = typeof customerObj === 'object' ? customerObj.email : null;
  const name = typeof customerObj === 'object' ? customerObj.name : null;
  const k = keyFor(customerId, email);
  if (!k) continue;
  const rec = getRecord(account, k.key, customerId, email, name);
  rec.bad_subscription_statuses.add(sub.status);
}

// ---- Determine delinquency + serialize records ----
const delinquentRecords = [];
for (const rec of records.values()) {
  const delinquent =
    rec.failed_charge_count >= 2 ||
    rec.max_attempt_count >= 2 ||
    rec.bad_subscription_statuses.size > 0;
  if (!delinquent) continue;
  delinquentRecords.push({
    account: rec.account,
    customer_id: rec.customer_id,
    emails: Array.from(rec.emails).filter(Boolean),
    names: Array.from(rec.names).filter(Boolean),
    failed_charge_count: rec.failed_charge_count,
    last_failed_charge_at: rec.last_failed_charge_at,
    open_invoice_count: rec.open_invoice_count,
    max_attempt_count: rec.max_attempt_count,
    oldest_open_invoice_at: rec.oldest_open_invoice_at,
    bad_subscription_statuses: Array.from(rec.bad_subscription_statuses),
  });
}

// ---- Attribution: match each delinquent record to a fleet_standing row ----
// Build fleet-row match-key sets once.
const fleetMatchIndex = fleetRows.map(row => {
  const aliasTokens = (row.aliases || '').split('|').map(t => normKey(t)).filter(Boolean);
  const clientLabelKey = normKey(row.client_label);
  const boxSlugKey = normKey(row.box_slug);
  const stripeCustIdKey = normKey(row.stripe_customer_id);
  return { row, aliasTokens, clientLabelKey, boxSlugKey, stripeCustIdKey };
});

const attributed = [];
const unattributed = [];

for (const rec of delinquentRecords) {
  let matchedRow = null;
  let matchedVia = null;

  const custIdKey = normKey(rec.customer_id);
  const emailKeys = rec.emails.map(normEmail);
  const nameKeys = rec.names.map(n => normKey(n));

  for (const fx of fleetMatchIndex) {
    // 1) Strongest: exact Stripe customer id match against the row's stored id.
    if (custIdKey && fx.stripeCustIdKey && fx.stripeCustIdKey === custIdKey) {
      matchedRow = fx.row; matchedVia = 'stripe_customer_id'; break;
    }
    // 2) Email match against alias tokens (primary signal per investigation).
    if (emailKeys.some(e => fx.aliasTokens.includes(e))) {
      matchedRow = fx.row; matchedVia = 'email_in_aliases'; break;
    }
    // 3) Customer id appearing as an alias token (e.g. seeded manually).
    if (custIdKey && fx.aliasTokens.includes(custIdKey)) {
      matchedRow = fx.row; matchedVia = 'customer_id_in_aliases'; break;
    }
    // 4) Fallback name match against client_label (weak signal - business
    //    names on Stripe customers are known to defeat this; kept only as a
    //    last resort per the build spec).
    if (fx.clientLabelKey && nameKeys.includes(fx.clientLabelKey)) {
      matchedRow = fx.row; matchedVia = 'name_in_client_label'; break;
    }
  }

  const summary = {
    account: rec.account,
    customer_id: rec.customer_id,
    emails: rec.emails,
    names: rec.names,
    failed_charge_count: rec.failed_charge_count,
    open_invoice_count: rec.open_invoice_count,
    max_attempt_count: rec.max_attempt_count,
    bad_subscription_statuses: rec.bad_subscription_statuses,
  };

  if (matchedRow) {
    attributed.push({
      box_slug: matchedRow.box_slug,
      client_label: matchedRow.client_label,
      good_standing: matchedRow.good_standing === true,
      matched_via: matchedVia,
      signal: summary,
    });
  } else {
    unattributed.push(summary);
  }
}

// ---- Totals per signal type and per account ----
const totals = { bceo_main: { failed_charges: 0, open_invoices: 0, bad_subscriptions: 0, delinquent_customers: 0 },
                  convert_and_flow: { failed_charges: 0, open_invoices: 0, bad_subscriptions: 0, delinquent_customers: 0 } };
for (const rec of delinquentRecords) {
  const t = totals[rec.account];
  if (!t) continue;
  t.delinquent_customers += 1;
  if (rec.failed_charge_count >= 2) t.failed_charges += 1;
  if (rec.max_attempt_count >= 2) t.open_invoices += 1;
  if (rec.bad_subscription_statuses.length > 0) t.bad_subscriptions += 1;
}

return [{
  json: {
    fleetRows: fleetRows,
    attributed: attributed,
    unattributed: unattributed,
    totals: totals,
    counts: {
      charges_pulled: charges.length,
      invoices_pulled: invoices.length,
      subscriptions_pulled: subscriptions.length,
      delinquent_customers: delinquentRecords.length,
    },
  },
}];

const input = $input.first().json;
const fleetRows = input.fleetRows || [];
const attributed = input.attributed || [];
const unattributed = input.unattributed || [];
const totals = input.totals || {};
const counts = input.counts || {};

// box_slug -> list of attributed delinquency entries for that box
const byBox = new Map();
function byBoxAdd(k, a) {
  if (!byBox.has(k)) byBox.set(k, []);
  byBox.get(k).push(a);
}
for (const a of attributed) {
  const k = a.box_slug || '(no box_slug)';
  byBoxAdd(k, a);
}

function fmtSignal(s) {
  const parts = [];
  if (s.failed_charge_count >= 2) parts.push('failed_charges=' + s.failed_charge_count);
  if (s.max_attempt_count >= 2) parts.push('open_invoice(attempt=' + s.max_attempt_count + ',count=' + s.open_invoice_count + ')');
  if (s.bad_subscription_statuses && s.bad_subscription_statuses.length) parts.push('subscription=' + s.bad_subscription_statuses.join('/'));
  return parts.join(', ');
}

const lines = [];
lines.push('FLEET STANDING <-> STRIPE -- DELINQUENCY REPORT (report-only, no writes)');
lines.push('Generated: ' + new Date().toISOString());
lines.push('Fleet boxes: ' + fleetRows.length + ' | Charges/Invoices/Subs pulled: ' + counts.charges_pulled + '/' + counts.invoices_pulled + '/' + counts.subscriptions_pulled);
lines.push('Delinquent Stripe customers found: ' + counts.delinquent_customers + ' (attributed=' + attributed.length + ', unattributed=' + unattributed.length + ')');
lines.push('');

// Section 1: ACTION -- delinquent AND currently good_standing = true
const actionRows = [];
for (const [boxSlug, entries] of byBox.entries()) {
  const anyGood = entries.some(e => e.good_standing === true);
  if (anyGood) actionRows.push({ boxSlug, entries });
}
lines.push('1) ACTION -- delinquent but good_standing=TRUE (' + actionRows.length + ')');
if (actionRows.length === 0) {
  lines.push('  none');
} else {
  let shown = 0;
  for (const r of actionRows) {
    if (shown >= 20) { lines.push('  (+' + (actionRows.length - shown) + ' more)'); break; }
    const e = r.entries[0];
    lines.push('  - ' + r.boxSlug + ' (' + (e.client_label || '') + ') [' + e.signal.account + '] ' + fmtSignal(e.signal) + ' via=' + e.matched_via);
    shown++;
  }
}
lines.push('');

// Section 2: OK -- delinquent and already good_standing = false (count only)
let okCount = 0;
for (const entries of byBox.values()) {
  if (entries.every(e => e.good_standing === false)) okCount++;
}
lines.push('2) OK -- delinquent, good_standing already FALSE: ' + okCount + ' box(es)');
lines.push('');

// Section 3: REVIEW -- good_standing=false but NO delinquency signal found
const flaggedSlugs = new Set(byBox.keys());
const reviewRows = fleetRows.filter(r => r.good_standing === false && !flaggedSlugs.has(r.box_slug));
lines.push('3) REVIEW -- good_standing=FALSE, no Stripe delinquency signal (' + reviewRows.length + ')');
if (reviewRows.length === 0) {
  lines.push('  none');
} else {
  let shown = 0;
  for (const r of reviewRows) {
    if (shown >= 20) { lines.push('  (+' + (reviewRows.length - shown) + ' more)'); break; }
    lines.push('  - ' + r.box_slug + ' (' + (r.client_label || '') + ')');
    shown++;
  }
}
lines.push('');

// Section 4: UNATTRIBUTED delinquents
lines.push('4) UNATTRIBUTED delinquents -- no fleet box match (' + unattributed.length + ')');
if (unattributed.length === 0) {
  lines.push('  none');
} else {
  let shown = 0;
  for (const u of unattributed) {
    if (shown >= 20) { lines.push('  (+' + (unattributed.length - shown) + ' more)'); break; }
    const emailStr = (u.emails && u.emails.length) ? u.emails.join(',') : '(no email)';
    const nameStr = (u.names && u.names.length) ? u.names.join('/') : '(no name)';
    lines.push('  - [' + u.account + '] cust=' + (u.customer_id || '(none)') + ' email=' + emailStr + ' name=' + nameStr + ' ' + fmtSignal(u));
    shown++;
  }
}
lines.push('');

// Section 5: Totals per signal type and per account
lines.push('5) TOTALS');
for (const acct of Object.keys(totals)) {
  const t = totals[acct];
  lines.push('  ' + acct + ': delinquent=' + t.delinquent_customers + ' failed_charges=' + t.failed_charges + ' open_invoices=' + t.open_invoices + ' bad_subscriptions=' + t.bad_subscriptions);
}

let report = lines.join('\n');
if (report.length > 3500) {
  report = report.slice(0, 3450) + '\n...[truncated, ' + report.length + ' chars total]';
}

return [{ json: { text: report } }];
